/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for i in [1,2,3,5,6,7,10,17]:
    links=[]
    for ref in r.pages[i].get('/Annots',[]):
        a=ref.get_object().get('/A',{})
        u=a.get('/URI')
        if u and str(u) not in links: links.append(str(u))
    print('PAGE',i+1,'LINKS',len(links))
    for u in links[:12]:print(u)
PY"
